// === Tab: mySketch ===
let num = 2000;
let noiseScale = 500, noiseStrength = 1;
let particles = [];
let flowField;
let colorScheme;
let pressStartTime;
let maxPressure = 1000; // Maximum press duration in milliseconds
let attractors = []; // Array to store attractor points

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);
  noStroke();

  flowField = new FlowField();
  colorScheme = new ColorScheme();

  for (let i = 0; i < num; i++) {
    let loc = createVector(random(width*1.2), random(height), random(1, 3));
    let angle = 0;
    let dir = createVector(cos(angle), sin(angle));
    let velocity = random(0.5, 2);
    particles[i] = new Particle(loc, dir, velocity);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  fill(0, 0, 0, 10);
  noStroke();
  rect(0, 0, width, height);

  flowField.update();

  for (let i = 0; i < particles.length; i++) {
    particles[i].run();
  }

  // Draw attractors
  for (let attractor of attractors) {
    attractor.display();
  }
}

function mousePressed() {
  pressStartTime = millis();
  // Create a new attractor at mouse position
  attractors.push(new Attractor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

class FlowField {
  constructor() {
    this.resolution = 10;
    this.cols = ceil(width / this.resolution);
    this.rows = ceil(height / this.resolution);
    this.field = new Array(this.cols * this.rows);
    this.zoff = 0;
    this.initField(); // Initialize the field
  }

  initField() {
    for (let i = 0; i < this.field.length; i++) {
      this.field[i] = createVector(0, 0); // Initialize with zero vectors
    }
  }

  update() {
    let xoff = 0;
    for (let x = 0; x < this.cols; x++) {
      let yoff = 0;
      for (let y = 0; y < this.rows; y++) {
        let index = x + y * this.cols;
        var angle = noise(xoff, yoff, this.zoff) * TWO_PI * noiseStrength;
        let v = p5.Vector.fromAngle(angle);
        v.setMag(1);
        this.field[index] = v;
        yoff += 0.1;
      }
      xoff += 0.1;
    }
    this.zoff += 0.01;
  }
}

class Particle {
  constructor(_loc, _dir, _velocity) {
    this.loc = _loc;
    this.dir = _dir;
    this.velocity = _velocity;
    this.color = null; // We'll set this in the update method
  }

  run() {
    this.move();
    this.checkEdges();
    this.update();
  }

  move() {
    let x = floor(this.loc.x / flowField.resolution);
    let y = floor(this.loc.y / flowField.resolution);
    x = constrain(x, 0, flowField.cols - 1);
    y = constrain(y, 0, flowField.rows - 1);
    var index = x + y * flowField.cols;
    let force = flowField.field[index];

    if (force) {
      this.dir = force.copy();
    } else {
      this.dir = createVector(random(-1, 1), random(-1, 1)).normalize();
    }

    // Apply attraction forces
    for (let attractor of attractors) {
      let attractionForce = attractor.attract(this.loc);
      this.dir.add(attractionForce);
    }

    let vel = this.dir.copy();
    vel.mult(this.velocity);
    this.loc.add(vel);
  }

  checkEdges() {
    if (this.loc.x < 0 || this.loc.x > width || this.loc.y < 0 || this.loc.y > height) {    
      this.loc.x = random(width*1.2);
      this.loc.y = random(height);
    }
  }

  update() {
    let pressure = 1;
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      pressure = min((millis() - pressStartTime) / maxPressure, 1);
    }
    let size = map(pressure, 0, 1, this.loc.z, this.loc.z * 3);

    // Update color here
    this.color = colorScheme.getColor(this.loc.x / width, this.loc.y / height);

    noStroke();
    fill(this.color);
    ellipse(this.loc.x, this.loc.y, size);
  }
}

class ColorScheme {
  constructor() {
    this.baseHue = random(360);
    this.hueRange = 60;
  }

  getColor(x, y) {
    let hue = (this.baseHue + this.hueRange * sin(x * PI) * cos(y * PI)) % 360;
    return color(hue, 80, 100);
  }
}

class Attractor {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.strength = 0.5; // Adjust this to change attraction strength
  }

  attract(particlePos) {
    var force = p5.Vector.sub(this.pos, particlePos);
    let distance = force.mag();
    distance = constrain(distance, 5, 25);
    force.normalize();
    let strength = (this.strength * 25) / (distance * distance);
    force.mult(strength);
    return force;
  }

  display() {
    noStroke();
    fill(0, 0, 100, 0.5); // White color with some transparency
    ellipse(this.pos.x, this.pos.y, 10, 10);
  }
}

